package com.aistock.scheduler.task;
import static org.mockito.Mockito.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class TaskWorkerTest {
 @Test void unknownTaskTypeCannotDispatchMarketOrPrediction(){var r=mock(TaskRepository.class);var m=mock(MarketRefreshClient.class);var reads=mock(MarketReceiptClient.class);var p=mock(PredictionTaskClient.class);var c=new TaskRepository.Claim(UUID.randomUUID().toString(),UUID.randomUUID().toString(),"SH600030",LocalDate.of(2026,10,9),Instant.now().plusSeconds(120),"UNKNOWN",null,null);when(r.pendingReceipts(anySet())).thenReturn(List.of());when(r.claim(any(),anySet())).thenReturn(c);new TaskWorker(r,m,reads,p,"test",false).runOnce();verifyNoInteractions(m,reads,p);verify(r).finish(eq(c),argThat(x->"FAILED".equals(x.state())&&"TASK_TYPE_UNSUPPORTED".equals(x.errorCode())),any());}
 @Test void unknownPendingTypeCannotReadMarketReceipt(){var r=mock(TaskRepository.class);var m=mock(MarketRefreshClient.class);var reads=mock(MarketReceiptClient.class);var p=mock(PredictionTaskClient.class);var c=new TaskRepository.Claim(UUID.randomUUID().toString(),UUID.randomUUID().toString(),"SH600030",LocalDate.of(2026,10,9),Instant.now().plusSeconds(120),"UNKNOWN",null,null);when(r.pendingReceipts(anySet())).thenReturn(List.of(c));new TaskWorker(r,m,reads,p,"test",false).runOnce();verifyNoInteractions(m,reads,p);verify(r).reconcile(eq(c),argThat(x->"TASK_TYPE_UNSUPPORTED".equals(x.errorCode())),any());}
}
